from pathlib import Path
import re

from lfx.custom import Component
from lfx.io import (
    MessageTextInput,
    StrInput,
    BoolInput,
    IntInput,
    Output,
)
from lfx.schema.data import Data


class LocalExactSearch(Component):
    display_name = "Local File Search"

    description = (
        "Search local files by filename, file extension, or exact text/code. "
        "Pass the user's COMPLETE QUESTION to this tool. "
        "Use for questions about whether files exist, filenames, extensions, "
        "or exact text/code contained in files."
    )

    icon = "Search"
    name = "LocalExactSearch"

    inputs = [
        MessageTextInput(
            name="query",
            display_name="User Question",
            info=(
                "Pass the COMPLETE user question exactly as written. "
                "The component decides whether to search filenames/extensions "
                "or file contents."
            ),
            required=True,
            tool_mode=True,
        ),

        StrInput(
            name="folder",
            display_name="Folder",
            value="/home/lucia-zifcakova/Downloads",
            required=True,
        ),

        BoolInput(
            name="recursive",
            display_name="Recursive",
            value=True,
        ),

        BoolInput(
            name="case_sensitive",
            display_name="Case Sensitive",
            value=False,
            advanced=True,
        ),

        StrInput(
            name="extensions",
            display_name="Content Search Extensions",
            value=".py,.R,.r,.txt,.md,.json,.yaml,.yml,.csv,.sh,.cpp,.c,.h,.hpp,.html,.htm",
            advanced=True,
        ),

        IntInput(
            name="max_results",
            display_name="Max Results",
            value=100,
            advanced=True,
        ),

        IntInput(
            name="context_lines",
            display_name="Context Lines",
            value=1,
            advanced=True,
        ),
    ]

    outputs = [
        Output(
            name="results",
            display_name="Search Results",
            method="search_files",
            types=["Data"],
        ),
    ]

    def _extract_extension(self, query: str) -> str | None:
        q = query.lower().strip()

    # Explicit extensions: ".html", ".py", etc.
        m = re.search(
            r"\.(html?|py|r|txt|md|csv|json|ya?ml|sh|cpp|c|h|hpp)\b",
            q,
        )

        if m:
            ext = m.group(1).lower()

            if ext in {"html", "htm"}:
                return ".html"

            return "." + ext

    # Natural language.
    # Keep these deliberately permissive because small local models
    # often transform "is there an HTML file?" into "html",
    # "content html", "find html", etc.
        aliases = {
            "html": ".html",
            "python": ".py",
            "markdown": ".md",
            "csv": ".csv",
            "json": ".json",
            "yaml": ".yaml",
            "yml": ".yml",
            "r script": ".r",
            "shell": ".sh",
            "bash": ".sh",
            "cpp": ".cpp",
        }

        for phrase, extension in aliases.items():
            if phrase in q:
                return extension

        return None


    def _extract_filename(self, query: str) -> str | None:
        """
        Detect filenames mentioned in a question.
        Example:
        'what is 262111936_multiqc_report.html about?'
        """

        matches = re.findall(
            r"\b[\w.\-]+\.(?:html?|py|r|txt|md|csv|json|ya?ml|sh|cpp|c|h|hpp)\b",
            query,
            flags=re.IGNORECASE,
        )

        if matches:
            return matches[0]

        return None

    def _extract_pattern(self, query: str) -> str:
        query = query.strip()

        # Prefer quoted text
        quoted = re.findall(r"""["']([^"']+)["']""", query)

        if quoted:
            return quoted[0].strip()

        # from x import y MUST come before plain import
        m = re.search(
            r"\b(from\s+[A-Za-z_][A-Za-z0-9_.]*\s+import\s+[A-Za-z_][A-Za-z0-9_., ]*)",
            query,
            flags=re.IGNORECASE,
        )

        if m:
            return m.group(1).strip()

        # import module
        m = re.search(
            r"\b(import\s+[A-Za-z_][A-Za-z0-9_.]*)",
            query,
            flags=re.IGNORECASE,
        )

        if m:
            return m.group(1).strip()

        # def function
        m = re.search(
            r"\b(def\s+[A-Za-z_][A-Za-z0-9_]*)",
            query,
            flags=re.IGNORECASE,
        )

        if m:
            return m.group(1).strip()

        # pandas.read_csv, re.compile, etc.
        code_tokens = re.findall(
            r"\b[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)+\b",
            query,
        )

        if code_tokens:
            return code_tokens[0]

        return query

    def search_files(self) -> Data:
        root = Path(self.folder).expanduser().resolve()

        if not root.exists():
            raise ValueError(f"Folder does not exist: {root}")

        if not root.is_dir():
            raise ValueError(f"Path is not a directory: {root}")

        query = str(self.query or "").strip()

        if not query:
            raise ValueError("User question cannot be empty.")

        max_results = max(1, int(self.max_results or 100))

        # =====================================================
        # 1. Filename search
        # =====================================================

        filename = self._extract_filename(query)

        if filename:
            matches = []

            paths = root.rglob("*") if self.recursive else root.glob("*")

            for path in paths:
                if not path.is_file():
                    continue

                if path.name.lower() == filename.lower():
                    matches.append(
                        {
                            "file_name": path.name,
                            "file_path": str(path),
                            "relative_path": str(path.relative_to(root)),
                        }
                    )

                if len(matches) >= max_results:
                    break

            result = {
                "search_type": "filename",
                "query_received": query,
                "filename": filename,
                "folder_searched": str(root),
                "match_count": len(matches),
                "matches": matches,
            }

            result["message"] = (
                f"FOUND {len(matches)} file(s) named {filename!r}."
                if matches
                else f"NO FILE FOUND named {filename!r}."
            )

            self.status = result["message"]
            return Data(data=result)

        # =====================================================
        # 2. Extension search
        # =====================================================

        wanted_extension = self._extract_extension(query)

        if wanted_extension:
            matching_files = []

            paths = root.rglob("*") if self.recursive else root.glob("*")

            for path in paths:
                if not path.is_file():
                    continue

                suffix = path.suffix.lower()

                # Treat html and htm separately but allow html request to find both
                if wanted_extension == ".html":
                    is_match = suffix in {".html", ".htm"}
                else:
                    is_match = suffix == wanted_extension.lower()

                if is_match:
                    matching_files.append(
                        {
                            "file_name": path.name,
                            "file_path": str(path),
                            "relative_path": str(path.relative_to(root)),
                        }
                    )

                if len(matching_files) >= max_results:
                    break

            result = {
                "search_type": "filename_extension",
                "query_received": query,
                "extension": wanted_extension,
                "folder_searched": str(root),
                "match_count": len(matching_files),
                "matches": matching_files,
            }

            result["message"] = (
                f"FOUND {len(matching_files)} file(s) with extension "
                f"{wanted_extension!r}."
                if matching_files
                else f"NO FILES FOUND with extension {wanted_extension!r}."
            )

            self.status = result["message"]
            return Data(data=result)

        # =====================================================
        # 3. Exact content search
        # =====================================================

        pattern = self._extract_pattern(query)

        allowed_extensions = None

        if self.extensions and self.extensions.strip():
            allowed_extensions = {
                (
                    ext.strip()
                    if ext.strip().startswith(".")
                    else "." + ext.strip()
                ).lower()
                for ext in self.extensions.split(",")
                if ext.strip()
            }

        flags = 0 if self.case_sensitive else re.IGNORECASE
        matcher = re.compile(re.escape(pattern), flags)

        paths = root.rglob("*") if self.recursive else root.glob("*")

        matches = []
        files_checked = 0
        context_n = max(0, int(self.context_lines or 0))

        for path in paths:
            if not path.is_file():
                continue

            if (
                allowed_extensions is not None
                and path.suffix.lower() not in allowed_extensions
            ):
                continue

            files_checked += 1

            try:
                text = path.read_text(
                    encoding="utf-8",
                    errors="ignore",
                )
            except OSError:
                continue

            lines = text.splitlines()

            for index, line in enumerate(lines):
                if not matcher.search(line):
                    continue

                start = max(0, index - context_n)
                end = min(len(lines), index + context_n + 1)

                context = "\n".join(
                    f"{i + 1}: {lines[i]}"
                    for i in range(start, end)
                )

                matches.append(
                    {
                        "file_name": path.name,
                        "file_path": str(path),
                        "relative_path": str(path.relative_to(root)),
                        "line_number": index + 1,
                        "matching_line": line.strip(),
                        "context": context,
                    }
                )

                if len(matches) >= max_results:
                    break

            if len(matches) >= max_results:
                break

        result = {
            "search_type": "exact_content",
            "query_received": query,
            "search_pattern_used": pattern,
            "folder_searched": str(root),
            "files_checked": files_checked,
            "match_count": len(matches),
            "matches": matches,
        }

        if matches:
            result["message"] = (
                f"FOUND {len(matches)} exact matches for {pattern!r}."
            )
        else:
            result["message"] = (
                f"NO MATCHES FOUND for exact text {pattern!r}. "
                f"Searched {files_checked} files."
            )

        self.status = result["message"]

        return Data(data=result)
